import React from 'react';
import { useAuth } from '../../hooks/useAuth';
import { FiLogOut, FiUser, FiBell } from 'react-icons/fi';

const AdminNavbar = () => {
  const { user, logout } = useAuth();

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-blue-900 text-white shadow-lg">
      <div className="flex items-center justify-between px-6 py-3">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-yellow-400 rounded-xl flex items-center justify-center font-bold text-blue-900 text-lg shadow-md transform -rotate-3">
            SC
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">
              <span className="text-yellow-400">SC</span> Academy Admin
            </h1>
            <p className="text-xs text-blue-300 font-medium">School Management System</p>
          </div>
        </div>

        <div className="flex items-center space-x-3">
          <button className="relative p-2 rounded-lg hover:bg-blue-800 transition text-blue-300 hover:text-white">
            <FiBell size={18} />
            <span className="text-sm font-medium">{user?.username || 'Admin'}</span>
          </button>
          <button
            onClick={logout}
            className="flex items-center space-x-1 bg-red-600 hover:bg-red-700 px-3 py-1.5 rounded-lg transition-colors text-sm"
          >
            <FiLogOut />
            <span>Logout</span>
          </button>
        </div>
      </div>
    </nav>
  );
};

export default AdminNavbar;
